class MockDataMatrix(DataMatrix):
    """Mock a data matrix with emission yields for all populations."""

    def __init__(
        self,
        seey: EmissionData,
        ebeey: EmissionData,
        ibeey: EmissionData,
        teey: EmissionData,
    ) -> None:
        """Set emission yield for SEs, EBEs, IBEs."""
        self.data_matrix = [
            [seey, None, None],
            [ebeey, None, None],
            [ibeey, None, None],
            [teey, None, None],
        ]

    def has_all_mandatory_files(self, *args, **kwargs) -> bool:
        """Skip this check."""
        return True


